import Component from 'flarum/common/Component';
import { percent, t } from '../util';
export default class StatusBadge extends Component {
  view() {
    const mailing = this.attrs.mailing;
    // "Sent" over a mailing that reached nobody would be a lie in green.
    const status = mailing.status === 'sent' && mailing.sentCount === 0 && mailing.failedCount > 0 ? 'failed' : mailing.status;
    const label = mailing.status === 'sending' ? t('status.sending_percent', {
      percent: percent(mailing.sentCount + mailing.failedCount, mailing.recipientTotal)
    }) : t(`status.${status}`);
    return m("span", {
      className: `HeraldStatus HeraldStatus--${status}`
    }, label);
  }
}
flarum.reg.add('ernestdefoe-herald', 'forum/components/StatusBadge', StatusBadge);